head.b:skin:
/*--------------------------------------------------
Theme Name: AstraNova News Pro
Author: Osman Studio
License: Commercial Premium License
Version: 1.0
---------------------------------------------------*/

:root{
  --primary:#0d6efd;
  --dark:#0f172a;
  --light:#f8fafc;
  --text:#1e293b;
}

*{
  margin:0;
  padding:0;
  box-sizing:border-box;
}

body{
  font-family:'Inter',sans-serif;
  background:var(--light);
  color:var(--text);
}

a{
  text-decoration:none;
  color:var(--primary);
}

.container{
  width:95%;
  max-width:1200px;
  margin:auto;
}

/* Header */
header{
  background:#fff;
  border-bottom:1px solid #e5e7eb;
  position:sticky;
  top:0;
  z-index:999;
}

.logo{
  font-size:28px;
  font-weight:800;
  padding:15px 0;
}

.nav{
  display:flex;
  gap:20px;
}

.nav a{
  font-weight:600;
  color:var(--dark);
}

/* Breaking News */
.breaking{
  background:var(--primary);
  color:#fff;
  padding:8px;
  font-size:14px;
}

/* Post Grid */
.post-grid{
  display:grid;
  grid-template-columns:repeat(auto-fit,minmax(280px,1fr));
  gap:20px;
  margin:30px 0;
}

.post-card{
  background:#fff;
  border-radius:12px;
  overflow:hidden;
  box-shadow:0 4px 12px rgba(0,0,0,.05);
  transition:.3s;
}

.post-card:hover{
  transform:translateY(-5px);
}

.post-card img{
  width:100%;
  height:200px;
  object-fit:cover;
}

.post-content{
  padding:15px;
}

.post-title{
  font-size:18px;
  font-weight:700;
  margin-bottom:10px;
}

/* Footer */
footer{
  background:var(--dark);
  color:#fff;
  padding:40px 0;
  margin-top:40px;
}

footer p{
  text-align:center;
  font-size:14px;
}

/* Dark Mode */
.dark-mode{
  background:#0f172a;
  color:#fff;
}
